import { parseDraft, type MemberDraft, type StepKey } from '../schemas/member'
import { StorageError, type MemberRepository } from '../storage/MemberRepository'

export type SubmissionResult =
  | { ok: true; dossierNumber: string | null }
  | { ok: false; message: string; step?: StepKey }

/**
 * Final validation then storage. The dossier number comes from the repository
 * (generated by the database in production). Never logs personal data.
 *
 * @param honeypot value of the hidden anti-bot field; when filled, the submission is silently dropped.
 */
export async function submitMembership(draft: MemberDraft, honeypot: string, repo: MemberRepository): Promise<SubmissionResult> {
  const parsed = parseDraft(draft)
  if (!parsed.success) {
    return { ok: false, step: parsed.step, message: 'Certaines informations sont incomplètes. Vérifiez la section indiquée.' }
  }

  if (honeypot.trim() !== '') return { ok: true, dossierNumber: null }

  try {
    const { dossier_number } = await repo.create(parsed.data)
    return { ok: true, dossierNumber: dossier_number }
  } catch (error) {
    const message =
      error instanceof StorageError ? error.message : "L'envoi n'a pas abouti. Vérifiez votre connexion puis réessayez."
    return { ok: false, message: `${message} Vos réponses sont conservées sur cette page.` }
  }
}
